----------------------
---- MY PROGRAMS -----
----------------------

local terminal    = "kitty"
local fileManager  = "thunar"
local menu         = "rofi -show drun"
local browser      = "brave"
local mainMod      = "SUPER" -- Sets "Windows" key as main modifier

------------------
---- MONITORS ----
------------------
-- Dica: se as portas trocarem de nome, use output = "desc:<descrição do hyprctl monitors>"
local main = { output = "DP-2", w = 1920, h = 1080, hz = 100 }
local side = { output = "DP-1", w = 1920, h = 1080, hz = 144 }

-- Rotacionado 90°: largura e altura lógicas se invertem
local sideW, sideH = side.h, side.w

hl.monitor({
    output   = main.output,
    mode     = ("%dx%d@%d"):format(main.w, main.h, main.hz),
    position = "0x0",
    scale    = 1,
})

hl.monitor({
    output    = side.output,
    mode      = ("%dx%d@%d"):format(side.w, side.h, side.hz),
    -- colado à esquerda do principal e centralizado na vertical
    position  = ("%dx%d"):format(-sideW, math.floor((main.h - sideH) / 2)),
    scale     = 1,
    transform = 1, -- 90°: base do monitor virada para a esquerda
})

hl.workspace_rule({ workspace = "1",  monitor = main.output, default = true, persistent = true })
hl.workspace_rule({ workspace = "10", monitor = side.output, default = true, persistent = true })

-------------------
---- AUTOSTART ----
-------------------
hl.on("hyprland.start", function()
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("~/.config/hypr/scripts/set-wallpapers.sh")
    hl.exec_cmd("waybar")
    hl.exec_cmd("~/.config/waybar/assets/spotify_notify.sh")
    hl.exec_cmd("hypridle")

    -- substitui os dois "sleep 2 && hyprctl dispatch ..." antigos
    hl.timer(function()
        hl.dispatch(hl.dsp.focus({ monitor = main.output }))
        hl.dispatch(hl.dsp.focus({ workspace = 1 }))
    end, { timeout = 2000, type = "oneshot" })
end)
